 const change=e=>{const el=e.target,d=el.dataset;if(d.wsTask){state().tasks[d.wsTask]=el.checked;saveRender();}else if(d.wsActive!==undefined){ws().activeProject=el.value;saveRender();}else if(d.wsMilestone){ws().milestones[d.wsMilestone]=el.checked;if(!el.checked){const n=mapNodes().find(x=>x.id===d.wsMilestone);for(const key of n?.checks||[])state().tasks[key]=false;}saveRender();}else if(d.wsProduction){ws().production[d.wsProduction]=el.tagName==='SELECT'?el.value:finite(el.value,0);saveRender();}else if(d.wsExplode!==undefined){explode=el.checked;viewer?.setExploded(explode);}else if(d.wsSpeed!==undefined){speed=Number(el.value);viewer?.setSpeed(speed);}else if(d.wsVideoFile!==undefined){const file=el.files[0];if(!file)return;if(!file.type.startsWith('video/')){c.toast('Selecciona un archivo de vídeo.');return;}if(localUrl)URL.revokeObjectURL(localUrl);localUrl=URL.createObjectURL(file);localFile=file.name;chapter=0;c.render();}};
 const input=e=>{const el=e.target,d=el.dataset;if(d.wsProduction){clearTimeout(productionTimer);const field=d.wsProduction,value=el.value;productionTimer=setTimeout(()=>{ws().production[field]=finite(value,0);c.save();c.render();document.querySelector(`[data-ws-production="${field}"]`)?.focus();},180);}else if(d.wsProjectNotes){ws().projectNotes[d.wsProjectNotes]=el.value;c.save();}else if(d.wsLayer!==undefined){layer=Number(el.value);viewer?.setLayer(layer);content.querySelector('[data-ws-layer-label]').textContent=layer>Math.max(...currentBp.blocks.map(b=>b.y))?'Todas':String(layer);}else if(d.wsTimeline!==undefined){viewer?.seek(Number(el.value));updateStep(Number(el.value));}};
