 let lastStep=-1;function updateStep(t){if(!currentBp)return;const total=currentBp.steps.length*8,time=t%total,index=Math.min(currentBp.steps.length-1,Math.floor(time/8));lessonStep=index;const range=document.querySelector('[data-ws-timeline]');if(range&&document.activeElement!==range)range.value=time;if(lastStep===index&&document.querySelector('[data-ws-step-title]')?.textContent===currentBp.steps[index].title)return;lastStep=index;const s=currentBp.steps[index];for(const [sel,value]of [['[data-ws-step-title]',s.title],['[data-ws-step-text]',s.text],['[data-ws-step-number]',`${String(index+1).padStart(2,'0')} / ${currentBp.steps.length}`]]){const el=document.querySelector(sel);if(el)el.textContent=value;}}
